 void open(){page("creator-entry","Estúdio do Criador","Suas histórias. Seu público. Seus resultados.");get("/application",r->{JSONObject app=r.optJSONObject("application");if(app!=null&&app.optString("status").equals("banned")){a.empty(a.body,"shield","Acesso de criador suspenso",app.optString("reason"));a.button(a.body,"Falar com o suporte",CARD,()->a.complete.support());return;}if(a.role.equals("admin")||app!=null&&app.optString("status").equals("approved")){dashboard();return;}if(app!=null&&app.optString("status").equals("pending")){waiting();return;}a.title(a.body,"Transforme histórias em uma comunidade",25);a.text(a.body,"Acompanhe visualizações válidas, seguidores e estimativas por produção em um espaço só seu.",15,MUTED);a.gap(a.body,20);a.menu("chart","Seu desempenho","Total de views e resultado de cada série",()->a.info("Resultados do criador","A medição começa nesta versão. Não criamos visualizações retroativas."));a.menu("shield","Cadastro privado","Nome, sobrenome, nascimento e selfie",()->information());a.button(a.body,"Quero ser criador",RED,()->information());});}
 void information(){page("creator-information","Vamos conhecer você","Etapa 1 de 2 · informações privadas");EditText name=a.field(a.body,"NOME","Seu nome",false),surname=a.field(a.body,"SOBRENOME","Seu sobrenome",false);name.setText(first);surname.setText(last);TextView date=a.label(birth.isEmpty()?"Selecionar data de nascimento":dateLabel(birth),16,WHITE);date.setPadding(a.dp(16),a.dp(16),a.dp(16),a.dp(16));date.setBackground(a.outline(CARD,12));a.body.addView(date);date.setOnClickListener(v->{Calendar cal=Calendar.getInstance();DatePickerDialog picker=new DatePickerDialog(a,(d,y,m,day)->{birth=String.format(Locale.US,"%04d-%02d-%02d",y,m+1,day);date.setText(dateLabel(birth));},cal.get(Calendar.YEAR)-18,cal.get(Calendar.MONTH),cal.get(Calendar.DAY_OF_MONTH));picker.getDatePicker().setMaxDate(System.currentTimeMillis());picker.show();});a.gap(a.body,12);a.text(a.body,"Cadastro disponível a partir de 18 anos. Estes dados não aparecem no perfil público.",13,MUTED);a.button(a.body,"Continuar para selfie",RED,()->{first=name.getText().toString().trim();last=surname.getText().toString().trim();if(first.length()<2||last.length()<2||birth.isEmpty()){a.notice("Preencha seu nome, sobrenome e nascimento.",true);return;}face();});}
 String dateLabel(String iso){String[] s=iso.split("-");return s.length==3?s[2]+"/"+s[1]+"/"+s[0]:iso;}
 void face(){page("creator-selfie","Sua selfie de cadastro","Etapa 2 de 2 · acesso privado");a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);preview=new ImageView(a);preview.setScaleType(ImageView.ScaleType.CENTER_CROP);preview.setBackground(a.outline(CARD,24));a.body.addView(preview,new LinearLayout.LayoutParams(-1,a.dp(240)));showPhoto();a.text(a.body,"Fotografe seu rosto em um local iluminado. A selfie fica privada e poderá ser consultada pelo administrador. Não há reconhecimento facial nem prova automática de identidade.",14,MUTED);a.button(a.body,selfie.isEmpty()?"Abrir câmera":"Tirar outra selfie",CARD,()->{photoPage=a.generation;try{a.startActivityForResult(new Intent(MediaStore.ACTION_IMAGE_CAPTURE).putExtra("android.intent.extras.CAMERA_FACING",1),61);}catch(ActivityNotFoundException e){a.notice("Nenhum aplicativo de câmera disponível neste aparelho.",true);}});CheckBox consent=new CheckBox(a);consent.setText("Autorizo o uso privado destes dados e da selfie para o cadastro. A liberação é automática e pode ser suspensa pelo administrador. A foto será removida após 30 dias pela rotina de limpeza ou ao retirar o cadastro.");consent.setTextColor(WHITE);consent.setChecked(accepted);a.body.addView(consent);consent.setOnCheckedChangeListener((v,on)->accepted=on);a.button(a.body,"Enviar cadastro",RED,()->a.safe(()->{if(selfie.isEmpty()||!accepted){a.notice("Capture a selfie e aceite o uso dos dados.",true);return;}post("/application",a.obj("first_name",first,"last_name",last,"birth_date",birth,"selfie",selfie,"consent",true),r->{selfie="";first="";last="";birth="";accepted=false;waiting();});}));a.button(a.body,"Voltar às informações",BG,()->information());}
 void showPhoto(){if(preview==null||selfie.isEmpty())return;try{byte[] bytes=android.util.Base64.decode(selfie,2);preview.setImageBitmap(BitmapFactory.decodeByteArray(bytes,0,bytes.length));}catch(Exception ignored){}}
 boolean result(int request,int result,Intent data){if(request!=61)return false;if(result==Activity.RESULT_OK&&data!=null&&data.getExtras()!=null&&photoPage==a.generation){Object raw=data.getExtras().get("data");if(raw instanceof Bitmap){ByteArrayOutputStream bytes=new ByteArrayOutputStream();((Bitmap)raw).compress(Bitmap.CompressFormat.JPEG,90,bytes);selfie=android.util.Base64.encodeToString(bytes.toByteArray(),2);showPhoto();}}return true;}
 void waiting(){page("creator-pending","Cadastro recebido","Estamos preparando seu acesso.");a.empty(a.body,"shield","Análise automática em andamento","Aguarde a liberação do seu cadastro. O administrador poderá revisar e suspender o acesso depois.");a.button(a.body,"Verificar situação",CARD,()->open());a.button(a.body,"Retirar meu cadastro",BG,()->withdraw());final int g=a.generation;a.handler.postDelayed(()->poll(g),12000);}
 void poll(int g){if(a.generation!=g)return;a.socialRequest("GET","/v10/application",null,r->{if(a.generation!=g)return;JSONObject app=r.optJSONObject("application");if(app!=null&&app.optString("status").equals("approved")){dashboard();return;}if(app!=null&&app.optString("status").equals("banned")){open();return;}a.handler.postDelayed(()->poll(g),12000);});}
 void dashboard(){page("creator-dashboard","Estúdio do Criador","Visão geral · resultados reais");a.button(a.body,"Gerenciar produções",RED,()->a.creatorHub.home());get("/studio",r->{LinearLayout row=a.row();metric(row,"Visualizações válidas",String.valueOf(r.optLong("views")));metric(row,"Seguidores",String.valueOf(r.optLong("followers")));a.body.addView(row);a.gap(a.body,12);LinearLayout finance=a.col();finance.setPadding(a.dp(18),a.dp(18),a.dp(18),a.dp(18));finance.setBackground(a.outline(CARD,18));a.text(finance,"GANHOS ESTIMADOS",12,MUTED);a.title(finance,money(r.optDouble("estimated_cents")),30);a.text(finance,"R$ 0,40 por 1.000 visualizações válidas",13,WHITE);a.text(finance,"Estimativa de acompanhamento. Não é saldo disponível para saque nem confirmação de pagamento.",12,MUTED);a.body.addView(finance);a.gap(a.body,20);a.title(a.body,"Desempenho por série",22);JSONArray items=r.optJSONArray("items");if(items!=null)for(int i=0;i<items.length();i++){JSONObject s=items.getJSONObject(i);LinearLayout card=a.col();card.setPadding(a.dp(15),a.dp(14),a.dp(15),a.dp(14));card.setBackground(a.outline(CARD,12));a.title(card,s.optString("title"),17);a.text(card,s.optLong("views")+" visualizações · "+money(s.optDouble("estimated_cents"))+" estimados",13,MUTED);a.body.addView(card);card.setOnClickListener(v->a.loadDetail(s.optInt("id"),"mine"));a.gap(a.body,10);}if(items==null||items.length()==0)a.empty(a.body,"film","Sua audiência começa aqui","Publique sua primeira produção para acompanhar os resultados.");a.menu("chart","Como as views são contadas","Regras e limites da medição",()->a.info("Visualizações e estimativas",r.optString("rule")+"\n\nRepetições da mesma conta no mesmo capítulo e dia não aumentam o total. Os valores são estimativas; ainda não existe saque automático. Proteções básicas não substituem uma auditoria antifraude."));a.menu("person","Perfil público","Foto, nome artístico e biografia",()->a.pro.profileEditor());a.menu("headset","Suporte do criador","Fale com o Cineo",()->a.complete.support());if(r.optJSONObject("application")!=null)a.button(a.body,"Retirar cadastro de criador",BG,()->withdraw());else a.button(a.body,"Ativar meu cadastro de criador",CARD,()->information());});}
 void metric(LinearLayout row,String label,String value){LinearLayout tile=a.col();tile.setPadding(a.dp(14),a.dp(16),a.dp(12),a.dp(16));tile.setBackground(a.outline(CARD,14));a.title(tile,value,25);a.text(tile,label,11,MUTED);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.rightMargin=a.dp(8);row.addView(tile,p);}
 void withdraw(){new AlertDialog.Builder(a).setTitle("Retirar cadastro de criador?").setMessage("Seu acesso de publicação será encerrado e a selfie removida. Suas produções não serão apagadas.").setNegativeButton("Cancelar",null).setPositiveButton("Retirar cadastro",(d,n)->post("/application/withdraw",new JSONObject(),r->open())).show();}
 void admin(String status){page("creator-admin","Criadores da plataforma","Liberações automáticas e suspensões");LinearLayout filters=a.row();String[] ids={"approved","pending","banned"},names={"Aprovados","Em análise","Suspensos"};for(int i=0;i<ids.length;i++){final String id=ids[i];a.button(filters,names[i],id.equals(status)?RED:CARD,()->admin(id)).setLayoutParams(new LinearLayout.LayoutParams(0,a.dp(48),1));}a.body.addView(filters);LinearLayout list=a.col();a.body.addView(list);adminPage(list,status,"");}
 void adminPage(LinearLayout list,String status,String before){get("/admin/creators?status="+status+(before.isEmpty()?"":"&before="+android.net.Uri.encode(before)),r->{JSONArray items=r.getJSONArray("items");if(items.length()==0&&before.isEmpty())a.empty(list,"person","Nenhum criador neste filtro","Os cadastros aparecerão aqui.");for(int i=0;i<items.length();i++){JSONObject s=items.getJSONObject(i);a.title(list,s.optString("first_name")+" "+s.optString("last_name"),18);a.text(list,"Cadastro: "+a.pro.date(s.optString("submitted_at"))+(s.optString("approved_at").isEmpty()?"":"\nLiberação automática: "+a.pro.date(s.optString("approved_at"))),12,MUTED);a.button(list,"Abrir cadastro",CARD,()->adminDetail(s.optString("user_id")));}if(!r.isNull("next")){Button more=a.button(list,"Carregar mais",CARD,()->{});more.setOnClickListener(v->{more.setVisibility(View.GONE);adminPage(list,status,r.optString("next"));});}});}
 void adminDetail(String uid){page("creator-admin-detail","Cadastro privado","A selfie não comprova a identidade.");a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);get("/admin/creator/"+uid,r->{JSONObject s=r.getJSONObject("application");a.title(a.body,s.optString("first_name")+" "+s.optString("last_name"),23);a.text(a.body,"Nascimento: "+dateLabel(s.optString("birth_date"))+"\nSituação: "+s.optString("status"),14,MUTED);String url=r.optString("selfie_url");if(!url.isEmpty()){ImageView photo=new ImageView(a);photo.setScaleType(ImageView.ScaleType.CENTER_CROP);a.body.addView(photo,new LinearLayout.LayoutParams(-1,a.dp(240)));a.images.execute(()->{try{byte[] bytes=a.art.download(url);Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);a.runOnUiThread(()->photo.setImageBitmap(bitmap));}catch(Exception ignored){}});}else a.text(a.body,"A selfie foi removida ou não está disponível.",13,MUTED);EditText reason=a.field(a.body,"MOTIVO","Descreva a decisão",false);a.button(a.body,s.optString("status").equals("banned")?"Restaurar acesso de criador":"Suspender acesso de criador",RED,()->new AlertDialog.Builder(a).setTitle("Confirmar decisão?").setMessage("A mudança será aplicada no servidor e registrada no histórico.").setNegativeButton("Cancelar",null).setPositiveButton("Confirmar",(d,n)->a.safe(()->post("/admin/creators",a.obj("user_id",uid,"action",s.optString("status").equals("banned")?"restore":"ban","reason",reason.getText().toString()),ok->adminDetail(uid)))).show());JSONArray events=r.optJSONArray("events");a.title(a.body,"Histórico de acesso",19);if(events!=null)for(int i=0;i<events.length();i++){JSONObject e=events.getJSONObject(i);a.text(a.body,e.optString("action")+" · "+a.pro.date(e.optString("created_at"))+"\n"+e.optString("reason"),12,MUTED);}});}
